import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modSub(a: Long, b: Long): Long {
    var res = a - b
    if (res < 0) res += MOD
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()
    if (n == 1) {
        println(1)
        return
    }

    val adj = Array(n) { ArrayList<Int>() }
    repeat(n - 1) {
        val st = StringTokenizer(br.readLine())
        val u = st.nextToken().toInt() - 1
        val v = st.nextToken().toInt() - 1
        adj[u].add(v)
        adj[v].add(u)
    }

    // dp[v][state][k]:
    // state 0: v unmatched, parent edge absent
    // state 1: v unmatched, parent edge present
    // state 2: v matched with child
    // k = 0 -> maximum matching size in subtree
    // k = 1 -> number of maximum matchings
    val dp = Array(n) { Array(3) { LongArray(2) } }

    fun dfs(v: Int, p: Int) {
        var prod0 = 1L
        var prod1 = 1L
        var prod2 = 1L

        for (to in adj[v]) {
            if (to == p) continue
            dfs(to, v)

            val a0 = dp[to][0][0]
            val b0 = dp[to][0][1]
            val a1 = dp[to][1][0]
            val b1 = dp[to][1][1]
            val a2 = dp[to][2][0]
            val b2 = dp[to][2][1]

            // child unmatched (parent edge absent)
            val best0 = maxOf(a0, a2)
            val ways0 = when {
                a0 > a2 -> b0
                a2 > a0 -> b2
                else -> (b0 + b2) % MOD
            }
            prod0 = prod0 * ways0 % MOD

            // child unmatched (parent edge present)
            val best1 = maxOf(a1, a2)
            val ways1 = when {
                a1 > a2 -> b1
                a2 > a1 -> b2
                else -> (b1 + b2) % MOD
            }
            prod1 = prod1 * ways1 % MOD

            // child matched with v
            val best2 = maxOf(a0, a1)
            val ways2 = when {
                a0 > a1 -> b0
                a1 > a0 -> b1
                else -> (b0 + b1) % MOD
            }
            prod2 = prod2 * ways2 % MOD
        }

        // state 0: v unmatched, parent edge absent
        dp[v][0][0] = 0
        dp[v][0][1] = prod0

        // state 1: v unmatched, parent edge present
        dp[v][1][0] = 0
        dp[v][1][1] = prod1

        // state 2: v matched with child
        dp[v][2][0] = 1
        dp[v][2][1] = prod2
    }

    dfs(0, -1)

    // Now count subsets of edges such that maximum matching is unique.
    // For each tree, number of subsets = product over edges of 2,
    // but we must subtract those where maximum matching is not unique.
    // Using DP above, we count configurations where maximum matching is unique.
    // For root, parent edge absent.
    val maxSize = maxOf(dp[0][0][0], dp[0][2][0])
    val ways = when {
        dp[0][0][0] > dp[0][2][0] -> dp[0][0][1]
        dp[0][2][0] > dp[0][0][0] -> dp[0][2][1]
        else -> (dp[0][0][1] + dp[0][2][1]) % MOD
    }

    // total subsets of edges = 2^(n-1)
    var total = 1L
    repeat(n - 1) {
        total = total * 2L % MOD
    }

    // configurations where maximum matching is not unique:
    // total - configurations where it is unique
    val ans = modSub(total, ways)
    println(ans)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun add(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun mul(a: Long, b: Long): Long = (a * b) % MOD

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()
    if (n == 1) {
        println(1)
        return
    }

    val g = Array(n) { IntArray(0) }
    val tmpAdj = Array(n) { mutableListOf<Int>() }
    repeat(n - 1) {
        val st = StringTokenizer(br.readLine())
        val u = st.nextToken().toInt() - 1
        val v = st.nextToken().toInt() - 1
        tmpAdj[u].add(v)
        tmpAdj[v].add(u)
    }
    for (i in 0 until n) {
        g[i] = tmpAdj[i].toIntArray()
    }

    val parent = IntArray(n) { -1 }
    val order = IntArray(n)
    var sz = 0
    order[sz++] = 0
    parent[0] = -2
    var idx = 0
    while (idx < sz) {
        val v = order[idx++]
        for (to in g[v]) {
            if (to == parent[v]) continue
            parent[to] = v
            order[sz++] = to
        }
    }

    // dp arrays:
    // dp0[v] = ways when v is unmatched and root of its component
    // dp1[v] = ways when v is matched with one of its children (unique choice)
    // dp2[v] = ways when maximum matching in component of v is not unique
    val dp0 = LongArray(n)
    val dp1 = LongArray(n)
    val dp2 = LongArray(n)

    // For each node, we consider its children and compute transitions.
    // We treat edges as either kept or removed; uniqueness is enforced via combinatorial conditions.
    for (i in n - 1 downTo 0) {
        val v = order[i]
        val children = mutableListOf<Int>()
        for (to in g[v]) if (to != parent[v]) children.add(to)

        if (children.isEmpty()) {
            // Leaf
            dp0[v] = 1L  // no edges, v unmatched
            dp1[v] = 0L
            dp2[v] = 0L
            continue
        }

        // For each child u, we know dp0[u], dp1[u], dp2[u].
        // We need to consider whether edge (v,u) is kept or removed.
        // We precompute for each child:
        // A_u: ways when edge (v,u) removed -> child subtree independent
        // B_u: ways when edge (v,u) kept but v not matched with u
        // C_u: ways when v matched with u (edge kept and chosen)
        val m = children.size
        val A = LongArray(m)
        val B = LongArray(m)
        val C = LongArray(m)

        for (idxChild in 0 until m) {
            val u = children[idxChild]
            // If edge removed: child component independent, must have unique maximum matching
            // So we can use dp0[u] + dp1[u], but not dp2[u].
            A[idxChild] = add(dp0[u], dp1[u])

            // Edge kept but v not matched with u:
            // Then u behaves as root with its parent edge present but not used.
            // That is similar to dp0[u] (u unmatched) plus dp1[u] (u matched with its child),
            // but we must ensure uniqueness; dp2[u] invalid.
            B[idxChild] = add(dp0[u], dp1[u])

            // v matched with u:
            // Then u must be in a state where it is matched with its parent (v).
            // For tree DP, that corresponds to u unmatched as root (dp0[u]) because
            // its parent edge is the one used; internal matching remains unique.
            C[idxChild] = dp0[u]
        }

        // Compute dp0[v]: v unmatched, root of component.
        // For each child, edge may be removed or kept (but not used to match v).
        // Also, maximum matching must be unique.
        // For uniqueness, for each child we must not create alternative choices.
        // That means we cannot have any child where both A and B are positive in a way
        // that introduces multiple maximum matchings. To enforce this combinatorially,
        // we count configurations where for every child, we choose either A or B,
        // and ensure that no combination yields multiple maxima.
        // This is complex; however, for trees, uniqueness is equivalent to having
        // no alternating cycles or paths, which in a forest reduces to local choices.
        // A safe sufficient condition is to require that for each child, either:
        // - we remove the edge and child's matching is unique, or
        // - we keep the edge but child's matching is unique and does not allow
        //   alternative augmenting paths. This is captured by using only dp0/dp1.
        //
        // We approximate by: dp0[v] = product over children of (A_u + B_u),
        // and dp2[v] will capture configurations that introduce non-uniqueness.
        var prodAB = 1L
        for (k in 0 until m) {
            prodAB = mul(prodAB, add(A[k], B[k]))
        }

        // Now count configurations where maximum matching is not unique.
        // Non-uniqueness arises when there is at least one child where both
        // choices A and B can lead to same matching size but different sets.
        // We approximate by inclusion-exclusion on children that allow both.
        // For tree constraints and dp2 propagation, we can treat any child
        // with dp2[u] > 0 as contributing to dp2[v].
        var nonUnique = 0L
        for (k in 0 until m) {
            val u = children[k]
            if (dp2[u] != 0L) {
                // If child's matching already non-unique, any configuration including it
                // leads to non-unique overall.
                var ways = dp2[u]
                // Other children can be any unique configuration (A+B)
                var other = 1L
                for (t in 0 until m) if (t != k) {
                    other = mul(other, add(A[t], B[t]))
                }
                nonUnique = add(nonUnique, mul(ways, other))
            }
        }

        dp0[v] = (prodAB - nonUnique + MOD) % MOD
        dp2[v] = nonUnique

        // Compute dp1[v]: v matched with exactly one child, and unique.
        // Choose child j to match with v using C[j], others use A or B.
        var sumMatch = 0L
        for (j in 0 until m) {
            if (C[j] == 0L) continue
            var ways = C[j]
            // For other children, choose A or B
            var other = 1L
            for (k in 0 until m) if (k != j) {
                other = mul(other, add(A[k], B[k]))
            }
            sumMatch = add(sumMatch, ways * other % MOD)
        }
        dp1[v] = sumMatch % MOD
    }

    // Root 0: we need total number of forests (edge deletions) such that
    // maximum matching is unique. Root can be unmatched or matched with a child.
    val ans = add(dp0[0], dp1[0])
    println(ans % MOD)
}

