            val u = children[idx]
            val a0 = dp0[u][0]
            val a1 = dp0[u][1]
            base1 += a0
            ways1 = modMul(ways1, a1)
        }
        dp1[v][0] = base1
        dp1[v][1] = ways1

        // For dp2[v] (matched to child)
        var best2 = -1_000_000_000
        var ways2 = 0L
        for (idx in 0 until k) {
            val u = children[idx]
            val curVal = base0 + 1 + delta0[idx]
