            if (to == parent[v]) continue
            childList.add(to)
        }
        val k = childList.size
        val base = LongArray(k)
        for (idx in 0 until k) {
            val c = childList[idx]
            val sum = modAdd(dp0[c], dp2[c])
            base[idx] = sum
            prodAll = modMul(prodAll, sum)
        }

        // dp0[v]
        dp0[v] = prodAll

        // dp1[v]
        var ways1 = 1L
        for (c in childList) {
            val sum = modAdd(dp0[c], dp2[c])
            ways1 = modMul(ways1, sum)
        }
        dp1[v] = ways1

        // dp2[v]
        var ways2 = 0L
        for (idx in 0 until k) {
            val c = childList[idx]
            val sum = modAdd(dp0[c], dp2[c])
            if (sum == 0L) continue
            val invPart = modMul(dp1[c], 1L)
            val contrib = modMul(prodAll, invPart)
            ways2 = modAdd(ways2, contrib)
        }
        dp2[v] = ways2
    }

    val ans = modAdd(dp0[0], dp2[0])
    println(ans % MOD)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun add(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun mul(a: Long, b: Long): Long = (a * b) % MOD

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()
    if (n == 1) {
        println(1)
        return
    }

    val adj = Array(n) { ArrayList<Int>() }
    repeat(n - 1) {
        val st = StringTokenizer(br.readLine())
        val u = st.nextToken().toInt() - 1
        val v = st.nextToken().toInt() - 1
        adj[u].add(v)
        adj[v].add(u)
    }

    val parent = IntArray(n) { -1 }
    val order = IntArray(n)
    var top = 0
    order[top++] = 0
    parent[0] = 0
    for (i in 0 until top) {
        val v = order[i]
        for (to in adj[v]) {
            if (to == parent[v]) continue
            parent[to] = v
            order[top++] = to
        }
    }

    // dp0[v], dp1[v], dp2[v]
    val dp0 = LongArray(n)
    val dp1 = LongArray(n)
    val dp2 = LongArray(n)

    for (i in n - 1 downTo 0) {
        val v = order[i]
        val children = ArrayList<Int>()
        for (to in adj[v]) if (to != parent[v]) children.add(to)

        if (children.isEmpty()) {
            // leaf
            dp0[v] = 1L
            dp1[v] = 0L
            dp2[v] = 0L
            continue
        }

        // Precompute for children
        val k = children.size
        val a = LongArray(k) // dp0 + dp1 + dp2
        val b = LongArray(k) // dp0 + dp1
        val c = LongArray(k) // dp0 + dp2
        for (idx in 0 until k) {
            val u = children[idx]
            val sAll = add(add(dp0[u], dp1[u]), dp2[u])
            val s01 = add(dp0[u], dp1[u])
            val s02 = add(dp0[u], dp2[u])
            a[idx] = sAll
            b[idx] = s01
            c[idx] = s02
        }

        // dp0[v]: v unmatched, unique maximum
        // product over children of (dp0+dp1+dp2)
        var prod0 = 1L
        for (idx in 0 until k) prod0 = mul(prod0, a[idx])
        dp0[v] = prod0

        // dp2[v]: v unmatched, multiple maximums
        // total ways where v unmatched minus dp0[v]
        var prod02 = 1L
        for (idx in 0 until k) prod02 = mul(prod02, c[idx])
        dp2[v] = (prod02 - dp0[v] + MOD) % MOD

        // dp1[v]: v matched, unique maximum
        // sum over child u: (dp0[u]+dp1[u]) * product over other children of (dp0+dp1+dp2)
        var sum1 = 0L
        // prefix and suffix products of a[]
        val pref = LongArray(k + 1)
        val suff = LongArray(k + 1)
        pref[0] = 1L
        for (idx in 0 until k) pref[idx + 1] = mul(pref[idx], a[idx])
        suff[k] = 1L
        for (idx in k - 1 downTo 0) suff[idx] = mul(suff[idx + 1], a[idx])

        for (idx in 0 until k) {
            val u = children[idx]
            val waysChild = b[idx]
            val others = mul(pref[idx], suff[idx + 1])
            sum1 = add(sum1, mul(waysChild, others))
        }
        dp1[v] = sum1
    }

    val root = 0
    val ans = add(add(dp0[root], dp1[root]), dp2[root])
    println(ans % MOD)
}

